entries[335932] = { ["name"] = "Death Chakram", ["text"] = "Covenant Ability\nInstant\nThrow a deadly chakram at your current target that will rapidly deal (31.6% of Attack Power) Shadow damage 7 times, bouncing to other targets if they are nearby. Enemies struck by Death Chakram take 10% more Physical damage from you and your pet for 10 sec.\n\nEach time the chakram deals damage, its damage is increased by 15% and you generate 3 Focus." }
entries[335933] = { ["name"] = "Abomination Limb", ["text"] = "Covenant Ability\nInstant\nBlood\nSprout an additional limb, dealing [(28.4% of Attack Power) * 13] Shadow damage over 12 sec to all nearby enemies. Deals reduced damage beyond 5 targets. Every 1 sec, an enemy is pulled to your location if they are further than 8 yds from you. The same enemy can only be pulled once every 4 sec.\n\nGain 3 Bone Shield charges instantly, and again every 6 sec.\n\nFrost\nSprout an additional limb, dealing [(28.4% of Attack Power) * 13] Shadow damage over 12 sec to all nearby enemies. Deals reduced damage beyond 5 targets. Every 1 sec, an enemy is pulled to your location if they are further than 8 yds from you. The same enemy can only be pulled once every 4 sec.\n\nGain Rime instantly, and again every 6 sec.\n\nUnholy\nSprout an additional limb, dealing [(28.4% of Attack Power) * 13] Shadow damage over 12 sec to all nearby enemies. Deals reduced damage beyond 5 targets. Every 1 sec, an enemy is pulled to your location if they are further than 8 yds from you. The same enemy can only be pulled once every 4 sec.\n\nGain Runic Corruption instantly, and again every 6 sec." }
entries[335934] = { ["name"] = "Fodder to the Flame", ["text"] = "Covenant Ability\nInstant\nYour damaging abilities have a chance to call forth a demon from the Theater of Pain for 25 sec. Throw Glaive deals lethal damage to the demon, which explodes on death, dealing (192.5% of Attack Power) Shadow damage to nearby enemies and healing you for 20% of your maximum health. The explosion deals reduced damage beyond 5 targets." }
entries[335935] = { ["name"] = "Adaptive Swarm", ["text"] = "Covenant Ability\nInstant\nCommand a swarm that heals (157.5% of Spell Power) or deals (150% of Spell Power) Shadow damage over 12 sec to a target, and increases the effectiveness of your periodic effects on them by 25%.\n\nUpon expiration, finds a new target, preferring to alternate between friend and foe up to 3 times." }
entries[335936] = { ["name"] = "Deathborne", ["text"] = "Covenant Ability\nInstant\nTransform into a powerful skeletal mage for 25 sec.\n\nWhile in the form of a skeletal mage, your Frostbolt, Fireball, and Arcane Blast hit up to 2 enemies near your target and your spell damage is increased by 15%." }
entries[335937] = { ["name"] = "Bonedust Brew", ["text"] = "Covenant Ability\nInstant\nHurl a brew created from the bones of your enemies at the ground, coating all targets struck for 10 sec. Your abilities have a 50% chance to affect the target a second time at 40% effectiveness as Shadow damage or healing.\n\n[ Mistweaver : Gust of Mists heals targets with your Bonedust Brew active for an additional (42% of Attack Power) / Brewmaster : Tiger Palm and Keg Smash reduces the cooldown of your brews by an additional 1 sec when striking enemies with your Bonedust Brew active / Windwalker : Spinning Crane Kick refunds 1 Chi when striking enemies with your Bonedust Brew active ]" }
entries[335938] = { ["name"] = "Freezing Pulse", ["text"] = "Instant\nMort pulses frost slime out every 5 sec., inflicting 0 Frost damage and applying Freezing Limbs to enemies within 10 yards and leaving behind a patch of Freezing Ground." }
entries[335939] = { ["name"] = "Vanquisher's Hammer", ["text"] = "Covenant Ability\nInstant\nThrows a hammer at your target dealing (136% of Spell Power) Shadow damage, and empowering your next [ Retribution : Templar's Verdict to automatically trigger Divine Storm ] [ Holy : Word of Glory to automatically trigger Light of Dawn /\n\nProtection\nWord of Glory to automatically trigger Shield of the Righteous ] with 25% increased effectiveness.\n\nGenerates 1 Holy Power." }
entries[335940] = { ["name"] = "Serrated Bone Spike", ["text"] = "Covenant Ability\nInstant\nEmbed a bone spike in the target, dealing (132% of Attack Power) Physical damage and (11% of Attack Power) Bleed damage every 3 sec until they die or leave combat.\n\nRefunds a charge when target dies.\n\nAwards 1 combo point plus 1 additional per active bone spike." }
entries[335941] = { ["name"] = "Primordial Wave", ["text"] = "Covenant Ability\nInstant\nRestoration\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power) and apply Riptide to them.\n\nYour next Healing Wave will also hit all targets affected by your Riptide for 60% of normal healing.\n\nElemental\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power).\n\nYour next Lava Burst will also hit all targets affected by your Flame Shock for 80% of normal damage.\n\nEnhancement\nBlast your target with a Primordial Wave, dealing (65% of Spell Power) Shadow damage and apply Flame Shock to an enemy, or heal an ally for (65% of Spell Power).\n\nYour next Lightning Bolt will also hit all targets affected by your Flame Shock for 150% of normal damage." }
entries[335942] = { ["name"] = "Decimating Bolt", ["text"] = "Covenant Ability\nInstant\nDemonology, Demonology (Destruction Warlock)\nHurl bolts of decimating magic at your target, dealing [4 * (34.5% of Spell Power)] Shadow damage and increasing the damage of your next 3 Demonbolts by 100%.\n\nDecimating Bolt's damage, and the bonus to Demonbolt both increase as your target's health decreases.\n\nDestruction, Destruction (Demonology Warlock)\nHurl bolts of decimating magic at your target, dealing [4 * (34.5% of Spell Power)] Shadow damage and increasing the damage of your next 3 Incinerates by 100%.\n\nDecimating Bolt's damage, and the bonus to Incinerate both increase as your target's health decreases.\n\nAffliction\nHurl bolts of decimating magic at your target, dealing [4 * (34.5% of Spell Power)] Shadow damage and increasing the damage of your next 3 by 100%.\n\nDecimating Bolt's damage, and the bonus to both increase as your target's health decreases." }
