entries[336036] = { ["name"] = "Marrowfang", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Marrowfang, Bonefang's progeny, was respected by Amarth the Harvester for her insatiable appetite, even if it disrupted any experiments that the sadistic commander wanted to run.\"\nDrop:\nNalthor the Rimebinder\nZone:\nThe Necrotic Wake (Mythic)\n\nDrop:\nChallenger's Cache\nZone:\nThe Necrotic Wake" }
