entries[336041] = { ["name"] = "Bonesewn Fleshroc", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Only expert flesh-stitchers who have demonstrated mastery over the magics of Maldraxxus are powerful enough to construct a deathroc of this size.\"\nProfession:\nAbominable Stitching\nZone:\nMaldraxxus" }
entries[336042] = { ["name"] = "Hulking Deathroc", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Deathrocs are stitched monstrosities from the discarded viscera, bone, and organs that were not required to construct soldiers for the House of Constructs.\"\nDrop:\nViolet Mistake\nZone:\nMaldraxxus" }
